import{_ as r,o as t,c as o,aj as a}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Hydration Missing Text","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG0512.md","filePath":"en/errors/NG0512.md"}'),n={name:"en/errors/NG0512.md"};function s(i,e,h,d,c,p){return t(),o("div",null,e[0]||(e[0]=[a('<h1 id="hydration-missing-text" tabindex="-1">Hydration Missing Text <a class="header-anchor" href="#hydration-missing-text" aria-label="Permalink to &quot;Hydration Missing Text&quot;">​</a></h1><p>This error is similar to the <a href="/en/errors/NG0500">error NG0500</a>, but it means Angular&#39;s hydration process expected a text node at a specific spot in the DOM and found nothing there. Check the <a href="/en/errors/NG0500">error NG0500</a> page for causes related to direct DOM manipulation.</p><h2 id="a-common-cause-the-server-html-changed-before-hydration" tabindex="-1">A common cause: the server HTML changed before hydration <a class="header-anchor" href="#a-common-cause-the-server-html-changed-before-hydration" aria-label="Permalink to &quot;A common cause: the server HTML changed before hydration&quot;">​</a></h2><p>Hydration reuses the text nodes that server-side rendering produced. If something removes or merges those text nodes before the browser runs the application, the node Angular looks for is gone.</p><p>Common sources are an HTML minifier, a proxy or CDN that rewrites the response, a browser extension, or application code that writes text with <code>innerHTML</code> outside of Angular.</p><h2 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h2><p>See the <a href="/en/errors/NG0500">error NG0500</a> for tips on debugging causes related to direct DOM manipulation.</p><p>Compare the HTML that the server sent with the HTML that the browser received. Use the page source rather than the element inspector, because the inspector shows the DOM after hydration already ran. If the text is present in the server response but missing in the browser, look for a tool in between that rewrites the HTML.</p><p>If you do not control the HTML for a component, you can add the <code>ngSkipHydration</code> attribute to its host node as a last resort. This disables hydration for that component and its children, and should be considered a bug that needs to be fixed.</p>',9)]))}const m=r(n,[["render",s]]);export{u as __pageData,m as default};
